import{createArenaDNA}from"./arena-generator.js";
import{createMutations}from"./mutation-engine.js";
import{createStoryDNA}from"./story-director.js";
import{hash,rng,semanticTokens,uid,unique}from"./utils.js";

export const AI_MONSTER_SCHEMA={type:"object",required:["semanticCore","semanticAliases","triggerConcepts","monsterName","monsterConcept","personality","visualMetaphor","visualTraits","symbolicArmor","arenaConcept","combatPersonality","storyBeats","introLines","defiantLines","crackedLines","breakdownLines","koLines","finisherFlavor","reusableElements"]};
const arr=(value,max=12)=>Array.isArray(value)?value.filter(x=>typeof x==="string"&&x.trim()).map(x=>x.trim()).slice(0,max):[];
const str=(value,max=160)=>typeof value==="string"?value.trim().slice(0,max):"";
export function validateAIDirectorDNA(value){if(!value||typeof value!=="object")return{ok:false,errors:["返回内容必须是 JSON 对象"]};const missing=AI_MONSTER_SCHEMA.required.filter(k=>value[k]==null),errors=[...missing.map(k=>`缺少 ${k}`)];for(const key of ["semanticCore","semanticAliases","triggerConcepts","visualTraits","symbolicArmor","combatPersonality","storyBeats","introLines","defiantLines","crackedLines","breakdownLines","koLines","reusableElements"])if(value[key]!=null&&!Array.isArray(value[key]))errors.push(`${key} 必须是数组`);if(!str(value.monsterName,40))errors.push("monsterName 不能为空");if(arr(value.semanticCore).length===0)errors.push("semanticCore 至少需要一项");return{ok:errors.length===0,errors}}
export function sanitizeAIDNA(value){return{semanticCore:arr(value.semanticCore,8),semanticAliases:arr(value.semanticAliases,12),triggerConcepts:arr(value.triggerConcepts,8),monsterName:str(value.monsterName,40),monsterConcept:str(value.monsterConcept,220),personality:str(value.personality,120),visualMetaphor:str(value.visualMetaphor,180),visualTraits:arr(value.visualTraits,10),symbolicArmor:arr(value.symbolicArmor,3),arenaConcept:str(value.arenaConcept,80),combatPersonality:arr(value.combatPersonality,6),storyBeats:arr(value.storyBeats,10),introLines:arr(value.introLines,4),defiantLines:arr(value.defiantLines,6),crackedLines:arr(value.crackedLines,6),breakdownLines:arr(value.breakdownLines,5),koLines:arr(value.koLines,3),finisherFlavor:str(value.finisherFlavor,100),reusableElements:arr(value.reusableElements,12),preferredWeaponThemes:arr(value.preferredWeaponThemes,4),destructionTargets:arr(value.destructionTargets,5),comicSetPieces:arr(value.comicSetPieces,4)}}
export function buildManualPrompt(text,mode){return`你是“打倒情绪小怪兽”的一次性 AI Director。只理解并艺术化下面这段中文，不做心理诊断，不提供建议，不写小说。把讨厌的行为或感受设计成一只可由本地 SVG primitive 绘制的怪物。名字必须来自核心视觉隐喻，不能随机拼词。Symbolic Armor 表示它为何让用户难受。台词必须活在怪物世界里，DEFIANT 阶段绝不求饶，CRACKED 阶段嘴硬，BREAKDOWN 才能慌乱。不要提 HP、代码、模型、语义、模块、生成器。只返回一个 JSON 对象，不要 Markdown。武器、破坏目标和喜剧场面仅提供主题建议，本地 Weapon Director 决定实际玩法。\n\n模式：${mode}\n用户表达：${text.slice(0,280)}\n\n严格字段：\n${JSON.stringify({semanticCore:["核心语义"],semanticAliases:["同义表达"],triggerConcepts:["概念标签"],monsterName:"名字",monsterConcept:"一句概念",personality:"人格",visualMetaphor:"视觉隐喻",visualTraits:["3-8个可画的视觉积木"],symbolicArmor:["1-3件象征护甲"],arenaConcept:"场景主题",combatPersonality:["2-4种行为"],storyBeats:["阶段事件"],introLines:["登场句"],defiantLines:["嚣张句"],crackedLines:["破相仍嘴硬"],breakdownLines:["崩坏句"],koLines:["败北句"],finisherFlavor:"终结风格",reusableElements:["可复用资产"],preferredWeaponThemes:["可选：hammer/chainsaw/pan/spring/magnet/vacuum/stamp/blower"],destructionTargets:["可选：适合破坏的场景物"],comicSetPieces:["可选：微型喜剧场面"]},null,2)}`}
export function aiAssetFromPayload(payload,profile){const d=sanitizeAIDNA(payload),now=Date.now();return{monsterId:uid("ai"),createdAt:now,originalSemanticProfile:{concepts:profile.concepts,keyPhrase:profile.keyPhrase,coreBehavior:profile.coreBehavior},...d,personalityDNA:{description:d.personality},visualDNA:{metaphor:d.visualMetaphor,traits:d.visualTraits},storyDNA:{beats:d.storyBeats},combatDNA:{behaviors:d.combatPersonality},symbolicArmorDNA:d.symbolicArmor,arenaDNA:{concept:d.arenaConcept},dialogueDNA:{intro:d.introLines,defiant:d.defiantLines,cracked:d.crackedLines,breakdown:d.breakdownLines,ko:d.koLines},origin:"ai",timesReused:0,lastUsedAt:null,mutations:[],defeatHistory:[]}}
export function encounterFromAIAsset(asset,profile,options={}){const seed=options.seed??hash(`${asset.monsterId}|${Date.now()}|${Math.random()}`),random=rng(seed),mutations=createMutations(seed,options.recent||[]),traits=unique([...(asset.visualDNA?.traits||asset.visualTraits||[]),...(asset.reusableElements||[])]),blueprint={coreShape:["tower","cluster","spiral","frame","split","tangle","arch"][Math.floor(random()*7)],coreCount:1+Math.floor(random()*4),width:+(.68+random()*.72).toFixed(2),height:+(.68+random()*.8).toFixed(2),symmetry:["balanced","offset","lopsided","stacked","radial"][Math.floor(random()*5)],facePlacement:["center","high","low","split","side"][Math.floor(random()*5)],headCount:random()>.78?2:1,limbs:[0,2,4,6,8][Math.floor(random()*5)],locomotion:["feet","wheels","hover","tendrils","hops"][Math.floor(random()*5)],material:["metal","paper","neon","shadow","organic","glitch","glass"][Math.floor(random()*7)],anchorParts:traits.slice(0,6),scale:+(.8+random()*.36).toFixed(2),motion:["jitter","swagger","hover","stomp","wave","flicker"][Math.floor(random()*6)]},palette=[["#ff4f78","#552143","#ffd84d"],["#a56cff","#32235f","#64f0d2"],["#4bb7ff","#263d70","#ff63c2"]][Math.floor(random()*3)],rarity=random()>.86?"RARE":random()>.5?"UNCOMMON":"COMMON",armor=(asset.symbolicArmorDNA||asset.symbolicArmor||[]).slice(0,3).map((label,i)=>({id:`armor-ai-${i}`,label,trait:traits[i]||"mask",state:"intact",durability:2+i})),arena=createArenaDNA(profile.concepts,seed,mutations),story=createStoryDNA(profile,rarity,seed);return{version:4,id:uid("enc"),seed,origin:options.origin||"ai-library",sourceAssetIds:[asset.monsterId],createdAt:Date.now(),semanticDNA:{...profile,tokens:semanticTokens(profile.source),label:(asset.semanticCore||[]).join(" / ")},monsterDNA:{id:uid("monster"),name:asset.monsterName,rarity,maxHp:rarity==="RARE"?225:rarity==="UNCOMMON"?195:165,represents:asset.monsterConcept,visual:{blueprint,primaryColor:palette[0],secondaryColor:palette[1],accentColor:palette[2],eyes:blueprint.headCount*2,mouth:"grin",arms:blueprint.limbs,legs:blueprint.locomotion==="feet"?2:0,horns:random()>.7,texture:blueprint.material},personality:asset.personalityDNA?.description||asset.personality,combatPersonality:asset.combatDNA?.behaviors||asset.combatPersonality||[]},symbolicArmorDNA:armor.length?armor:[{id:"armor-ai-core",label:"象征外壳",trait:traits[0]||"mask",state:"intact",durability:2}],arenaDNA:arena,combatDNA:{behaviors:asset.combatDNA?.behaviors||asset.combatPersonality||[],powerFantasy:true,releaseTarget:100},storyDNA:{...story,beats:asset.storyDNA?.beats||asset.storyBeats||story.beats},dialogueDNA:{intro:asset.dialogueDNA?.intro||asset.introLines||[],taunt:asset.dialogueDNA?.defiant||asset.defiantLines||[],defiant:asset.dialogueDNA?.defiant||asset.defiantLines||[],cracked:asset.dialogueDNA?.cracked||asset.crackedLines||[],breakdown:asset.dialogueDNA?.breakdown||asset.breakdownLines||[],ko:asset.dialogueDNA?.ko||asset.koLines||[],grunts:["哼。","喂！","啧。"],nemesis:["又是你。"],special:["你居然找到了。"]},mutationDNA:mutations,novelty:{silhouette:`${blueprint.coreShape}:${blueprint.coreCount}:${blueprint.symmetry}:${blueprint.limbs}:${blueprint.locomotion}`,arena:`${arena.theme}:${arena.layout}`,colors:palette.join("-"),armor:armor.map(x=>x.label).join("+"),combat:(asset.combatPersonality||[]).join("+"),dialogueStyle:(asset.semanticCore||[])[0]||"ai",mutation:mutations.map(x=>x.id).join("+")||"classic",story:story.pattern},privacy:{rawPersisted:false}}}
export class AIDirectorAdapter{
  constructor(){this.provider="manual-chatgpt-bridge"}
  availability(){return{direct:false,reason:"当前静态 GitHub Pages 版本没有安全的服务器端会话与获批客户端，因此不在前端保存 OAuth 凭据。",manual:true}}
  buildPrompt(text,mode){return buildManualPrompt(text,mode)}
  parse(raw){let value;try{value=JSON.parse(raw)}catch{return{ok:false,errors:["无法解析 JSON，请只粘贴 ChatGPT 返回的 JSON 对象"]}}const result=validateAIDirectorDNA(value);return result.ok?{ok:true,value:sanitizeAIDNA(value)}:result}
  async generate(){throw new Error("Direct AI provider is not configured; use the manual bridge or local library")}
}
